shell_rule_posix.agent_file_after:
{
  "name": "auditx",
  "description": "shell_type probe agent",
  "prompt": "You are a terse probe agent. Run shell commands exactly as asked.",
  "tools": [
    "shell",
    "read"
  ],
  "permissions": {
    "rules": [
      {
        "capability": "shell",
        "match": [
          "echo AUDITX*"
        ],
        "effect": "allow"
      }
    ]
  }
}

